import{_ as e,o as n,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Petunjuk Versi dan Pemeliharaan Dokumen","description":"","frontmatter":{},"headers":[],"relativePath":"id/0099-文档版本与维护说明.md","filePath":"id/0099-文档版本与维护说明.md"}'),t={name:"id/0099-文档版本与维护说明.md"};function s(u,a,m,o,l,d){return n(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="petunjuk-versi-dan-pemeliharaan-dokumen" tabindex="-1">Petunjuk Versi dan Pemeliharaan Dokumen <a class="header-anchor" href="#petunjuk-versi-dan-pemeliharaan-dokumen" aria-label="Permalink to &quot;Petunjuk Versi dan Pemeliharaan Dokumen&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>99</td></tr><tr><td>Modul</td><td>Lampiran dan Materi Referensi</td></tr><tr><td>Kata Kunci Utama</td><td>manajemen versi, petunjuk pemeliharaan, norma dokumen, log pembaruan, pemeliharaan pengaturan</td></tr></tbody></table><h2 id="_1-gambaran-umum-sistem-dokumen" tabindex="-1">1. Gambaran Umum Sistem Dokumen <a class="header-anchor" href="#_1-gambaran-umum-sistem-dokumen" aria-label="Permalink to &quot;1. Gambaran Umum Sistem Dokumen&quot;">​</a></h2><p>Sistem pengaturan Peradaban Simbiosis Jangkar terdiri dari 100 dokumen Markdown, bernomor dari 00 hingga 99, dibagi menjadi sepuluh modul, dengan 10 dokumen di setiap modul. Sistem dokumen mengadopsi SPEC.md (Norma Pembuatan Dokumen) sebagai batasan ketat, 00-Gambaran Umum Alam Semesta Hengyuanzhou sebagai pedoman umum, dokumen setiap modul dikembangkan secara rinci dari dimensi yang berbeda, dan akhirnya dokumen lampiran 90-99 melakukan pengindeksan, kompilasi, dan pengorganisasian. Seluruh sistem dokumen membentuk basis pengetahuan pengaturan yang lengkap, konsisten secara logis, hierarkis, dan saling merujuk.</p><p>Desain sistem dokumen mengikuti tiga prinsip: &quot;modular, terstruktur, dapat diperluas&quot;. Modular berarti setiap dokumen berfokus pada topik tertentu dan mandiri lengkap; terstruktur berarti semua dokumen mengikuti norma format yang seragam, memudahkan pembacaan dan pencarian; dapat diperluas berarti sistem dokumen menyisakan ruang yang cukup untuk perluasan, dapat terus meningkatkan pengaturan melalui revisi dokumen yang ada dan penambahan konten baru.</p><h2 id="_2-aturan-penomoran-versi" tabindex="-1">2. Aturan Penomoran Versi <a class="header-anchor" href="#_2-aturan-penomoran-versi" aria-label="Permalink to &quot;2. Aturan Penomoran Versi&quot;">​</a></h2><p>Sistem dokumen mengadopsi aturan penomoran versi tiga tingkat: &quot;nomor versi utama.nomor versi sekunder.nomor revisi&quot;:</p><table tabindex="0"><thead><tr><th>Tingkat Versi</th><th>Aturan Penomoran</th><th>Kondisi Pemicu</th><th>Contoh</th></tr></thead><tbody><tr><td>Nomor versi utama</td><td>Bertambah mulai dari 1</td><td>Penyesuaian struktur penting pada sistem dokumen, seperti pembagian ulang modul, perubahan pengaturan inti</td><td>v1.0 → v2.0</td></tr><tr><td>Nomor versi sekunder</td><td>Bertambah mulai dari 0</td><td>Revisi substansial pada konten inti suatu dokumen, atau penambahan konten pengaturan penting</td><td>v1.0 → v1.1</td></tr><tr><td>Nomor revisi</td><td>Bertambah mulai dari 0</td><td>Koreksi teks, penyesuaian format, penyatuan istilah, dan perubahan non-substansial lainnya</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>Versi keseluruhan sistem dokumen saat ini adalah v1.0, yaitu versi rilis lengkap pertama. Setiap dokumen mencatat nomor versinya sendiri di blok informasi dokumennya, dan nomor versi keseluruhan sistem dokumen dicatat secara seragam dalam dokumen ini.</p><h2 id="_3-tinjauan-norma-format-dokumen" tabindex="-1">3. Tinjauan Norma Format Dokumen <a class="header-anchor" href="#_3-tinjauan-norma-format-dokumen" aria-label="Permalink to &quot;3. Tinjauan Norma Format Dokumen&quot;">​</a></h2><p>Semua dokumen harus mengikuti norma format seragam berikut (norma rinci lihat SPEC.md):</p><h3 id="_3-1-penamaan-file" tabindex="-1">3.1 Penamaan File <a class="header-anchor" href="#_3-1-penamaan-file" aria-label="Permalink to &quot;3.1 Penamaan File&quot;">​</a></h3><p>Format nama file adalah <code>XX-judul dokumen.md</code>, di mana XX adalah nomor dua digit dari 00 hingga 99, judul dalam bahasa Mandarin, tanpa spasi.</p><h3 id="_3-2-struktur-dokumen" tabindex="-1">3.2 Struktur Dokumen <a class="header-anchor" href="#_3-2-struktur-dokumen" aria-label="Permalink to &quot;3.2 Struktur Dokumen&quot;">​</a></h3><p>Setiap dokumen harus mengandung elemen struktur berikut:</p><ol><li><strong>Judul tingkat pertama</strong>: Judul dokumen (konsisten dengan nama file)</li><li><strong>Blok informasi dokumen</strong>: Tabel dengan nomor, modul, kata kunci utama (3-5)</li><li><strong>Teks utama</strong>: Setidaknya 3 bab dengan judul tingkat kedua, menggunakan elemen terstruktur seperti daftar dan tabel</li><li><strong>Penutup</strong>: Paragraf ringkasan singkat</li><li><strong>Dokumen terkait</strong>: Mencantumkan 2-3 nomor dan nama dokumen terkait</li></ol><h3 id="_3-3-persyaratan-jumlah-kata" tabindex="-1">3.3 Persyaratan Jumlah Kata <a class="header-anchor" href="#_3-3-persyaratan-jumlah-kata" aria-label="Permalink to &quot;3.3 Persyaratan Jumlah Kata&quot;">​</a></h3><p>Teks utama setiap dokumen tidak boleh kurang dari 800 karakter (tidak termasuk judul dan metadata).</p><h3 id="_3-4-gaya-penulisan" tabindex="-1">3.4 Gaya Penulisan <a class="header-anchor" href="#_3-4-gaya-penulisan" aria-label="Permalink to &quot;3.4 Gaya Penulisan&quot;">​</a></h3><ul><li>Gaya dokumen pengaturan yang serius dan sistematis, mirip ensiklopedia/kumpulan pengaturan</li><li>Menggunakan istilah seragam seperti &quot;Hengyuanzhou&quot;, &quot;jangkar&quot;, &quot;simbiosis&quot;</li><li>Pengaturan baru yang dilengkapi harus konsisten secara logis dengan pengaturan yang ada, sesuai dengan prinsip &quot;berbasis realitas, peningkatan hukum&quot;</li></ul><h2 id="_4-organisasi-dan-tanggung-jawab-pemeliharaan" tabindex="-1">4. Organisasi dan Tanggung Jawab Pemeliharaan <a class="header-anchor" href="#_4-organisasi-dan-tanggung-jawab-pemeliharaan" aria-label="Permalink to &quot;4. Organisasi dan Tanggung Jawab Pemeliharaan&quot;">​</a></h2><h3 id="_4-1-komite-pemeliharaan-pengaturan" tabindex="-1">4.1 Komite Pemeliharaan Pengaturan <a class="header-anchor" href="#_4-1-komite-pemeliharaan-pengaturan" aria-label="Permalink to &quot;4.1 Komite Pemeliharaan Pengaturan&quot;">​</a></h3><p>Komite Pemeliharaan Pengaturan adalah lembaga pemeliharaan tertinggi sistem dokumen, terdiri dari pencipta pengaturan berpengalaman, ahli verifikasi logika, dan perwakilan pengguna. Tanggung jawab intinya meliputi:</p><ul><li>Menyetujui struktur keseluruhan dan rencana revisi penting sistem dokumen</li><li>Memverifikasi perubahan pengaturan penting, memastikan konsistensi dengan pengaturan inti</li><li>Memutuskan sengketa pengaturan, memberikan penjelasan otoritatif</li><li>Mengorganisir secara teratur pemeriksaan mandiri konsistensi pengaturan lengkap</li><li>Menerbitkan pembaruan versi keseluruhan sistem dokumen</li></ul><h3 id="_4-2-pemelihara-modul" tabindex="-1">4.2 Pemelihara Modul <a class="header-anchor" href="#_4-2-pemelihara-modul" aria-label="Permalink to &quot;4.2 Pemelihara Modul&quot;">​</a></h3><p>Setiap modul menunjuk seorang pemelihara modul, yang bertanggung jawab atas pemeliharaan harian 10 dokumen modul tersebut. Tanggung jawabnya meliputi:</p><ul><li>Melacak konsistensi pengaturan dokumen di dalam modul</li><li>Memverifikasi permohonan revisi dokumen di dalam modul</li><li>Mengoordinasikan referensi silang antar dokumen di dalam modul</li><li>Mengumpulkan umpan balik dan saran pengguna tentang konten modul</li><li>Melaporkan secara teratur status pemeliharaan modul kepada Komite Pemeliharaan Pengaturan</li></ul><h3 id="_4-3-pencipta-dokumen" tabindex="-1">4.3 Pencipta Dokumen <a class="header-anchor" href="#_4-3-pencipta-dokumen" aria-label="Permalink to &quot;4.3 Pencipta Dokumen&quot;">​</a></h3><p>Setiap pencipta yang memenuhi syarat dapat berpartisipasi dalam pembuatan dan revisi dokumen. Tanggung jawab pencipta meliputi:</p><ul><li>Membuat atau merevisi dokumen sesuai dengan norma format</li><li>Memastikan konten yang dibuat lulus pemeriksaan tabel pemeriksaan mandiri kontradiksi pengaturan</li><li>Melampirkan instruksi revisi rinci saat mengirimkan revisi</li><li>Bekerja sama dengan pekerjaan verifikasi pemelihara dan komite</li></ul><h2 id="_5-proses-revisi" tabindex="-1">5. Proses Revisi <a class="header-anchor" href="#_5-proses-revisi" aria-label="Permalink to &quot;5. Proses Revisi&quot;">​</a></h2><h3 id="_5-1-proses-revisi-reguler" tabindex="-1">5.1 Proses Revisi Reguler <a class="header-anchor" href="#_5-1-proses-revisi-reguler" aria-label="Permalink to &quot;5.1 Proses Revisi Reguler&quot;">​</a></h3><ol><li><strong>Mengirimkan permohonan</strong>: Pencipta mengirimkan permohonan revisi kepada pemelihara modul, termasuk nomor dokumen yang direvisi, deskripsi konten revisi, dan alasan revisi.</li><li><strong>Verifikasi modul</strong>: Pemelihara modul memverifikasi konten revisi, dengan fokus pada pemeriksaan norma format dan konsistensi di dalam modul. Setelah lulus verifikasi, mengirimkannya kepada Komite Pemeliharaan Pengaturan.</li><li><strong>Persetujuan komite</strong>: Komite Pemeliharaan Pengaturan melakukan persetujuan akhir terhadap konten revisi, dengan fokus pada pemeriksaan konsistensi antar modul dan konsistensi pengaturan inti.</li><li><strong>Melaksanakan revisi</strong>: Setelah lulus persetujuan, pemelihara modul atau pencipta asli melaksanakan revisi dokumen.</li><li><strong>Memperbarui versi</strong>: Setelah revisi selesai, memperbarui nomor versi dokumen dan mencatatnya di log pembaruan dokumen ini.</li><li><strong>Sinkronisasi terkait</strong>: Jika konten revisi memengaruhi dokumen lain, dokumen terkait harus direvisi secara sinkron.</li></ol><h3 id="_5-2-proses-revisi-darurat" tabindex="-1">5.2 Proses Revisi Darurat <a class="header-anchor" href="#_5-2-proses-revisi-darurat" aria-label="Permalink to &quot;5.2 Proses Revisi Darurat&quot;">​</a></h3><p>Untuk situasi darurat di mana kontradiksi atau kesalahan pengaturan yang serius ditemukan, proses revisi darurat dapat dimulai:</p><ol><li><strong>Laporan darurat</strong>: Penemu segera melaporkan masalah tersebut kepada Komite Pemeliharaan Pengaturan.</li><li><strong>Persetujuan cepat</strong>: Komite menyelesaikan persetujuan darurat dalam 24 jam dan memberikan rencana revisi.</li><li><strong>Melaksanakan revisi</strong>: Menunjuk orang tertentu untuk segera melaksanakan revisi.</li><li><strong>Pencatatan setelahnya</strong>: Setelah revisi selesai, melengkapi catatan permohonan revisi dan verifikasi.</li></ol><h3 id="_5-3-revisi-lengkap-teratur" tabindex="-1">5.3 Revisi Lengkap Teratur <a class="header-anchor" href="#_5-3-revisi-lengkap-teratur" aria-label="Permalink to &quot;5.3 Revisi Lengkap Teratur&quot;">​</a></h3><p>Komite Pemeliharaan Pengaturan mengorganisir revisi lengkap sistem dokumen setahun sekali, termasuk:</p><ul><li>Pemeriksaan mandiri konsistensi pengaturan lengkap</li><li>Pemrosesan terpusat umpan balik pengguna</li><li>Penyatuan dan pembaruan sistem istilah</li><li>Pembaruan sinkron dokumen indeks</li><li>Pemeriksaan dan koreksi seragam format dokumen</li></ul><h2 id="_6-log-pembaruan" tabindex="-1">6. Log Pembaruan <a class="header-anchor" href="#_6-log-pembaruan" aria-label="Permalink to &quot;6. Log Pembaruan&quot;">​</a></h2><h3 id="v1-0-rilis-lengkap-pertama" tabindex="-1">v1.0 (Rilis Lengkap Pertama) <a class="header-anchor" href="#v1-0-rilis-lengkap-pertama" aria-label="Permalink to &quot;v1.0 (Rilis Lengkap Pertama)&quot;">​</a></h3><ul><li>Menyelesaikan pembuatan dan penerbitan semua 100 dokumen</li><li>Membangun struktur lengkap dan norma format sistem dokumen</li><li>Menyelesaikan cakupan konten sepuluh modul</li><li>Membangun sistem indeks lampiran (kamus istilah, indeks sistem, indeks hukum, kronik, katalog semua ras, tokoh dan organisasi, FAQ, tabel pemeriksaan mandiri, saran perluasan, petunjuk versi)</li></ul><h3 id="area-pencatatan-pembaruan-versi-selanjutnya" tabindex="-1">Area Pencatatan Pembaruan Versi Selanjutnya <a class="header-anchor" href="#area-pencatatan-pembaruan-versi-selanjutnya" aria-label="Permalink to &quot;Area Pencatatan Pembaruan Versi Selanjutnya&quot;">​</a></h3><p>(Konten pembaruan versi selanjutnya akan ditambahkan di sini, termasuk nomor versi, tanggal penerbitan, ringkasan konten pembaruan utama)</p><h2 id="_7-norma-referensi-dan-referensi-silang-dokumen" tabindex="-1">7. Norma Referensi dan Referensi Silang Dokumen <a class="header-anchor" href="#_7-norma-referensi-dan-referensi-silang-dokumen" aria-label="Permalink to &quot;7. Norma Referensi dan Referensi Silang Dokumen&quot;">​</a></h2><h3 id="_7-1-referensi-internal" tabindex="-1">7.1 Referensi Internal <a class="header-anchor" href="#_7-1-referensi-internal" aria-label="Permalink to &quot;7.1 Referensi Internal&quot;">​</a></h3><p>Referensi silang antar dokumen menggunakan format &quot;nomor dokumen-judul dokumen&quot;, misalnya, &quot;lihat Dokumen 84 &#39;Program Umum Protokol Arkeologi&#39;&quot;. Saat merujuk, harus memastikan bahwa dokumen yang dirujuk benar-benar ada dan nomor serta judulnya benar.</p><h3 id="_7-2-referensi-istilah" tabindex="-1">7.2 Referensi Istilah <a class="header-anchor" href="#_7-2-referensi-istilah" aria-label="Permalink to &quot;7.2 Referensi Istilah&quot;">​</a></h3><p>Saat menggunakan istilah inti untuk pertama kalinya, dapat menunjukkan bahwa harus merujuk ke item yang sesuai di Dokumen 90 &quot;Kamus Istilah&quot;. Tidak perlu mengulangi penunjukan saat menggunakan istilah yang sama kemudian.</p><h3 id="_7-3-referensi-eksternal" tabindex="-1">7.3 Referensi Eksternal <a class="header-anchor" href="#_7-3-referensi-eksternal" aria-label="Permalink to &quot;7.3 Referensi Eksternal&quot;">​</a></h3><p>Jika perlu merujuk materi nyata atau karya fiksi di luar sistem pengaturan, harus menunjukkan sumbernya dan menjelaskan dengan jelas bahwa referensi ini adalah materi referensi di bawah prinsip &quot;berbasis realitas&quot;, tidak mewakili adopsi lengkap kontennya oleh sistem pengaturan.</p><h2 id="_8-mekanisme-jaminan-kualitas" tabindex="-1">8. Mekanisme Jaminan Kualitas <a class="header-anchor" href="#_8-mekanisme-jaminan-kualitas" aria-label="Permalink to &quot;8. Mekanisme Jaminan Kualitas&quot;">​</a></h2><h3 id="_8-1-pemeriksaan-mandiri-kontradiksi-pengaturan" tabindex="-1">8.1 Pemeriksaan Mandiri Kontradiksi Pengaturan <a class="header-anchor" href="#_8-1-pemeriksaan-mandiri-kontradiksi-pengaturan" aria-label="Permalink to &quot;8.1 Pemeriksaan Mandiri Kontradiksi Pengaturan&quot;">​</a></h3><p>Semua dokumen yang baru dibuat dan direvisi harus lulus semua item pemeriksaan Dokumen 97 &quot;Tabel Pemeriksaan Mandiri Kontradiksi Pengaturan&quot;, termasuk lebih dari 40 pemeriksaan dalam tiga kategori: konsistensi pengaturan inti, konsistensi logika antar modul, dan norma format dokumen.</p><h3 id="_8-2-verifikasi-silang" tabindex="-1">8.2 Verifikasi Silang <a class="header-anchor" href="#_8-2-verifikasi-silang" aria-label="Permalink to &quot;8.2 Verifikasi Silang&quot;">​</a></h3><p>Setiap dokumen harus lulus verifikasi silang oleh setidaknya satu pencipta lain sebelum penerbitan formal, dengan fokus pada pemeriksaan konsistensi logika antar modul dan penyatuan istilah.</p><h3 id="_8-3-mekanisme-umpan-balik-pengguna" tabindex="-1">8.3 Mekanisme Umpan Balik Pengguna <a class="header-anchor" href="#_8-3-mekanisme-umpan-balik-pengguna" aria-label="Permalink to &quot;8.3 Mekanisme Umpan Balik Pengguna&quot;">​</a></h3><p>Sistem dokumen menetapkan saluran umpan balik pengguna, melalui mana pengguna dapat mengirimkan umpan balik dengan cara berikut:</p><ul><li>Melaporkan kontradiksi pengaturan dan kesalahan logika</li><li>Mengajukan masalah ketidakterpaduan istilah</li><li>Menyarankan pelengkapan atau revisi konten tertentu</li><li>Menunjukkan kesalahan format dan teks</li></ul><p>Semua umpan balik diproses secara terklasifikasi oleh pemelihara modul, dan umpan balik penting diajukan ke Komite Pemeliharaan Pengaturan untuk dibahas.</p><h3 id="_8-4-laporan-konsistensi-kuartalan" tabindex="-1">8.4 Laporan Konsistensi Kuartalan <a class="header-anchor" href="#_8-4-laporan-konsistensi-kuartalan" aria-label="Permalink to &quot;8.4 Laporan Konsistensi Kuartalan&quot;">​</a></h3><p>Komite Pemeliharaan Pengaturan menerbitkan satu &quot;Laporan Konsistensi Pengaturan&quot; setiap kuartal, isinya meliputi:</p><ul><li>Kontradiksi pengaturan yang ditemukan pada kuartal ini dan status pemrosesan</li><li>Statistik revisi dokumen pada kuartal ini</li><li>Kemajuan penyatuan istilah</li><li>Status pemrosesan umpan balik pengguna</li><li>Rencana pemeliharaan untuk kuartal berikutnya</li></ul><h2 id="_9-penyimpanan-dan-distribusi-dokumen" tabindex="-1">9. Penyimpanan dan Distribusi Dokumen <a class="header-anchor" href="#_9-penyimpanan-dan-distribusi-dokumen" aria-label="Permalink to &quot;9. Penyimpanan dan Distribusi Dokumen&quot;">​</a></h2><h3 id="_9-1-format-penyimpanan" tabindex="-1">9.1 Format Penyimpanan <a class="header-anchor" href="#_9-1-format-penyimpanan" aria-label="Permalink to &quot;9.1 Format Penyimpanan&quot;">​</a></h3><p>Semua dokumen disimpan dalam format Markdown (.md), memastikan keterbacaan lintas platform dan kenyamanan manajemen versi. Dokumen menggunakan pengkodean UTF-8, mendukung bahasa Mandarin dan karakter khusus.</p><h3 id="_9-2-struktur-direktori" tabindex="-1">9.2 Struktur Direktori <a class="header-anchor" href="#_9-2-struktur-direktori" aria-label="Permalink to &quot;9.2 Struktur Direktori&quot;">​</a></h3><p>Dokumen disimpan secara seragam di direktori <code>anchor-docs/</code>, dengan nama file dalam format <code>XX-judul dokumen.md</code>. SPEC.md, sebagai file norma, juga disimpan di direktori yang sama.</p><h3 id="_9-3-manajemen-versi" tabindex="-1">9.3 Manajemen Versi <a class="header-anchor" href="#_9-3-manajemen-versi" aria-label="Permalink to &quot;9.3 Manajemen Versi&quot;">​</a></h3><p>Disarankan untuk menggunakan sistem kontrol versi seperti Git untuk mengelola versi dokumen, melampirkan pesan commit rinci pada setiap pengiriman revisi, mencatat konten dan alasan revisi.</p><h3 id="_9-4-metode-distribusi" tabindex="-1">9.4 Metode Distribusi <a class="header-anchor" href="#_9-4-metode-distribusi" aria-label="Permalink to &quot;9.4 Metode Distribusi&quot;">​</a></h3><p>Sistem dokumen dapat didistribusikan dengan cara berikut:</p><ul><li>Dikemas sebagai file ZIP terkompresi untuk diunduh</li><li>Dideploy sebagai situs statis untuk penjelajahan online</li><li>Dikonversi ke format PDF atau EPUB untuk dibaca</li><li>Diimpor ke sistem manajemen pengetahuan untuk manajemen terstruktur</li></ul><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Petunjuk Versi dan Pemeliharaan Dokumen adalah &quot;konstitusi manajemen&quot; dari sistem pengaturan Peradaban Simbiosis Jangkar. Ini menetapkan aturan versi, organisasi pemeliharaan, proses revisi, mekanisme jaminan kualitas, dan metode penyimpanan serta distribusi sistem dokumen, memastikan bahwa sistem pengaturan besar yang terdiri dari 100 dokumen ini dapat selalu menjaga ketertiban dan konsistensi dalam proses pertumbuhan berkelanjutan. Sistem pengaturan yang baik tidak hanya membutuhkan konten yang luar biasa, tetapi juga mekanisme pemeliharaan yang sempurna untuk menjamin perkembangan sehat jangka panjangnya. Dokumen ini tepatnya adalah pembawa inti dari mekanisme tersebut.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>97-Tabel Pemeriksaan Mandiri Kontradiksi Pengaturan</li><li>90-Kamus Istilah</li><li>00-Gambaran Umum Alam Semesta Hengyuanzhou</li></ul>',77)])])}const h=e(t,[["render",s]]);export{p as __pageData,h as default};
